"""Depth scan of the paper's published 8-SAT angles on the clean16_8sat test sets vs WalkSATlm (same formulas).
Writes results/PAPER_QAOA_ADVANTAGE_8SAT.md + png."""
import json, numpy as np, common as CM
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
ns = CM.TEST_N; rng = np.random.default_rng(0)
def sl(y, nn=ns): return np.polyfit(nn, np.log2(y), 1)
def bci(C, nn=ns):
    b = [sl([np.median(rng.choice(C[n], len(C[n]))) for n in nn], nn)[0] for _ in range(1000)]; return np.percentile(b, [2.5, 97.5])
PS = [1, 2, 3, 4, 5, 6, 8, 10, 14, 30, 60]
Q = {p: {n: 1 / np.maximum(json.load(open(f"{CM.RES}/P{p}.json"))["test"][str(n)]["p"], 1e-12) for n in ns} for p in PS}
W = {n: json.load(open(f"{CM.RES}/W_n{n}.json")) for n in ns}
WT = {n: np.array(W[n]["tries"]) for n in ns}; WL = {n: np.array(W[n]["lookups"]) for n in ns}
TAB2 = {14: (-1.064, 0.326), 60: (-2.842, 0.302)}; WTAB = (-0.309, 0.325)
aT, aL = sl([np.median(WT[n]) for n in ns])[0], sl([np.median(WL[n]) for n in ns])[0]
ciT, ciL = bci(WT), bci(WL)
L = ["# How the paper gets a QAOA advantage over WalkSATlm on 8-SAT (PRX Quantum 5, 030348)", "",
     "_Auto-generated by `oct_explore/clean16_8sat/advantage.py`._ Same 100 fresh satisfiable 8-SAT test formulas per n (paper ensemble, r=176.54, Poisson m, literals with replacement, sat-only, solutions not required unique), n=8,12,16,20. "
     "QAOA = the paper's own published fixed angles (PhaseCraft qaoa_ksat_paper_data), untrained, exact 1/p. Exponent α: median cost ∝ 2^{αn}.", "",
     f"**WalkSATlm (our calibrated wslm.c, p=0.30 w1=6 w2=5) on the same formulas:** α = **{aT:.3f}** [{ciT[0]:.3f}, {ciT[1]:.3f}] in the paper's unit (tries = formula evaluations, each try = fresh start + n flips); "
     f"α = **{aL:.3f}** [{ciL[0]:.3f}, {ciL[1]:.3f}] in lookups (tries + flips). Paper Table II: 0.325 (tries). Our earlier n=8..22 reproduction: 0.316.", "",
     "| depth p | α median (ours, 95% CI) | α from 1/mean p | theory c(p)=0.69 p^-0.32 (paper Fig. 2) | Table II α | beats WalkSATlm α in tries? | in lookups? | median n=20 (shots) |", "|---|---|---|---|---|---|---|---|"]
AQ = {}
for p in PS:
    a = sl([np.median(Q[p][n]) for n in ns])[0]; ci = bci(Q[p]); AQ[p] = a
    mp = [np.mean(1 / Q[p][n]) for n in ns]; am = -sl(mp)[0]
    L.append(f"| {p} | **{a:.3f}** [{ci[0]:.3f}, {ci[1]:.3f}] | {am:.3f} | {0.69 * p ** -0.32:.3f} | {TAB2[p][1] if p in TAB2 else '—'} | {'yes' if ci[1] < aT else ('no' if ci[0] > aT else 'tie')} | {'yes' if ci[1] < aL else ('no' if ci[0] > aL else 'tie')} | {np.median(Q[p][20]):.3g} |")
pp = np.array(PS, float); a_ = np.array([AQ[p] for p in PS])
def cross(at):
    i = np.where(a_ < at)[0][0]; x0, x1 = np.log(pp[i - 1]), np.log(pp[i]); y0, y1 = a_[i - 1], a_[i]; return float(np.exp(x0 + (at - y0) * (x1 - x0) / (y1 - y0)))
cT, cL = cross(aT), cross(aL)
L += ["", f"**Crossover depth (QAOA α = WalkSATlm α, log-interpolated):** p* ≈ **{cT:.1f}** in the paper's unit (paper: ≈14), p* ≈ **{cL:.1f}** if WalkSATlm is charged per lookup.", ""]
fig, ax = plt.subplots(1, 2, figsize=(11, 4.2))
ax[0].semilogx(PS, a_, "o-", label="QAOA, paper angles (ours, median)"); ax[0].semilogx(PS, 0.69 * pp ** -0.32, "--", label="paper theory 0.69 p^-0.32")
ax[0].axhline(aT, color="k", label=f"WalkSATlm tries {aT:.3f}"); ax[0].axhline(aL, color="gray", ls=":", label=f"WalkSATlm lookups {aL:.3f}")
ax[0].scatter([14, 60], [0.326, 0.302], marker="x", color="r", zorder=5, label="paper Table II")
ax[0].set_xlabel("QAOA depth p"); ax[0].set_ylabel("α (median cost ∝ 2^{αn})"); ax[0].legend(fontsize=7); ax[0].grid(alpha=.3, which="both"); ax[0].set_title("8-SAT exponent vs depth")
for p in (4, 14, 60): ax[1].semilogy(ns, [np.median(Q[p][n]) for n in ns], "o-", label=f"QAOA p={p} (shots)")
ax[1].semilogy(ns, [np.median(WT[n]) for n in ns], "ks-", label="WalkSATlm (tries)"); ax[1].semilogy(ns, [np.median(WL[n]) for n in ns], "s:", color="gray", label="WalkSATlm (lookups)")
ax[1].set_xlabel("n"); ax[1].set_ylabel("median cost"); ax[1].set_xticks(ns); ax[1].legend(fontsize=7); ax[1].grid(alpha=.3, which="both"); ax[1].set_title("same 100 test formulas per n")
fig.tight_layout(); fig.savefig(f"{CM.ROOT}/results/paper_qaoa_advantage_8sat.png", dpi=150)
open(f"{CM.ROOT}/results/PAPER_QAOA_ADVANTAGE_8SAT.md", "w").write("\n".join(L) + "\n" + open(f"{CM.HERE}/VERDICT.md").read() if __import__("os").path.exists(f"{CM.HERE}/VERDICT.md") else "\n".join(L) + "\n")
print("\n".join(L))
